    const verification = runTestsCommand(root, verifyCommand);
    const acceptance = acceptanceCommand === verifyCommand ? verification : runTestsCommand(root, acceptanceCommand);
    return { verification, acceptance };
  };
  return {
    changed,
    execute(action) {
      const args = action?.args || {};
      if (action.action === "list_files") {
        const rawBase = args.path || ".";
        const base = inside(root, rawBase);
        const relativePath = relative(root, base);
        if (rawBase !== "." && rawBase !== "" && !readAdmitted(relativePath)) return observe({ error: `list_files path is outside declared readable paths: ${relativePath}` });
        const all = walk(root, base, [], Math.min(Number(args.max) || 250, 600));
        return observe({ files: all.filter(file => readAdmitted(file)) });
      }
      if (action.action === "search") {
        const query = String(args.query || "");
        if (!query) return observe({ error: "search requires args.query" });
        const rawBase = args.path || ".";
        const base = inside(root, rawBase);
        const relativePath = relative(root, base);
        if (rawBase !== "." && rawBase !== "" && !readAdmitted(relativePath)) return observe({ error: `search path is outside declared readable paths: ${relativePath}` });
        const hits = [];
        for (const file of walk(root, base, [], 600)) {
          if (!readAdmitted(file)) continue;
          const path = inside(root, file);
          let text;
          try { text = readFileSync(path, "utf8"); } catch { continue; }
